import type { NextConfig } from "next";
import { fileURLToPath } from "node:url";
import { responseHeaders } from "./src/shared/response-headers";

const config: NextConfig = {
  output: "standalone",
  outputFileTracingRoot: fileURLToPath(new URL("../..", import.meta.url)),
  transpilePackages: ["@capiro/ui"],
  poweredByHeader: false,
  turbopack: { root: fileURLToPath(new URL("../..", import.meta.url)) },
  async headers() {
    return [
      {
        source: "/(.*)",
        headers: responseHeaders,
      },
    ];
  },
};
export default config;

import { notFound } from "next/navigation";
import { ModuleScreen } from "../../../features/modules/ModuleScreen";
import { ConnectedModule } from "../../../shared/shell/ConnectedModule";
import { moduleCatalog } from "../../../shared/shell/module-catalog";

export default async function ModulePage({
  params,
}: {
  params: Promise<{ module: string }>;
}) {
  const { module } = await params;
  const descriptor = moduleCatalog.find(
    (candidate) => candidate.slug === module,
  );
  if (!descriptor) notFound();
  return (
    <ConnectedModule active={descriptor.slug}>
      <ModuleScreen module={descriptor.slug} />
    </ConnectedModule>
  );
}

"use client";
import { DocumentsLibrary, WorkflowCards } from "./WorkspaceLibrary";

import { useRouter, useSearchParams } from "next/navigation";
import { useState } from "react";
import {
  workspaceId,
  type WorkspaceLibraryDocument,
} from "../../../shared/capiro/operations/workspace-schemas";
import { ActionButton, Modal } from "../../../shared/module-ui";
import { HillDayEditor } from "./hillday/HillDayEditor";
import { HillDayWizard } from "./hillday/HillDayWizard";
import { NewsletterWorkflow } from "./newsletter/NewsletterWorkflow";
import { TemplateStudio } from "./templates/TemplateStudio";
import styles from "./workspace.module.css";
import { WorkspaceDraft } from "./WorkspaceDraft";
import { WorkspaceShares } from "./WorkspaceShares";
import { ProspectWorkspace } from "./prospects/ProspectWorkspace";

type View =
  | "documents"
  | "workflows"
  | "shares"
  | "templates"
  | "hillday"
  | "newsletter";
const tabs: { id: View; label: string }[] = [
  { id: "documents", label: "Documents" },
  { id: "workflows", label: "Workflows" },
  { id: "shares", label: "Client shares" },
];

export function WorkspaceScreen() {
  const searchParams = useSearchParams();
  const router = useRouter();
  const prospect = workspaceId.safeParse(searchParams.get("prospectId"));
  const initialView = searchParams.get("view");
  const requestedView: View =
    initialView === "hillday" ||
    initialView === "templates" ||
    initialView === "newsletter" ||
    initialView === "workflows" ||
    initialView === "shares"
      ? initialView
      : "documents";
  const parsedClient = workspaceId.safeParse(searchParams.get("clientId"));
  const requestedDraft = workspaceId.safeParse(searchParams.get("draftId"));
  const clientId = parsedClient.success ? parsedClient.data : undefined;
  const [view, setView] = useState<View>(requestedView);
  const [selected, setSelected] = useState<WorkspaceLibraryDocument>();
  const [createdId, setCreatedId] = useState<string>();
  const [newDocument, setNewDocument] = useState(false);
  const [routeKey, setRouteKey] = useState(() =>
    JSON.stringify([requestedView, clientId]),
  );
  if (routeKey !== JSON.stringify([requestedView, clientId])) {
    setRouteKey(JSON.stringify([requestedView, clientId]));
    setView(requestedView);
    setSelected(undefined);
    setCreatedId(undefined);
  }
  const back = () => {
    setSelected(undefined);
    setCreatedId(undefined);
    setView("documents");
  };
  if (searchParams.has("prospectId") && !prospect.success)
    return (
      <section role="alert">
        <h1>Prospect unavailable</h1>
        <p>A canonical prospect ID is required.</p>
      </section>
    );
  if (prospect.success) {
    const base = `/modules/workspace?prospectId=${encodeURIComponent(prospect.data)}`;
    return requestedDraft.success ? (
      <WorkspaceDraft
        key={`${prospect.data}:${requestedDraft.data}`}
        id={requestedDraft.data}
        prospectId={prospect.data}
        onClose={() => router.push(base)}
      />
    ) : (
      <ProspectWorkspace
        key={prospect.data}
        prospectId={prospect.data}
        onOpen={(id) =>
          router.push(`${base}&draftId=${encodeURIComponent(id)}`)
        }
      />
    );
  }
  if (requestedDraft.success)
    return (
      <WorkspaceDraft
        id={requestedDraft.data}
        onClose={() => {
          window.location.assign("/modules/workspace");
        }}
      />
    );
  if (view === "hillday")
    return (
      <HillDayWizard
        initialClientId={clientId}
        onClose={back}
        onCreated={(id) => {
          setCreatedId(id);
          setView("documents");
        }}
      />
    );
  if (view === "newsletter")
    return <NewsletterWorkflow initialClientId={clientId} onClose={back} />;
  if (view === "templates")
    return <TemplateStudio initialClientId={clientId} onClose={back} />;
  if (createdId || selected?.kind === "hillday")
    return <HillDayEditor id={createdId ?? selected!.id} onClose={back} />;
  if (selected?.kind === "draft")
    return <WorkspaceDraft id={selected.id} onClose={back} />;
  return (
    <section className={styles.screen} data-design-node="411:112533">
      <header className={styles.heading}>
        <div>
          <h1>Workspace</h1>
        </div>
        <div className={styles.actions}>
          <ActionButton onClick={() => setView("templates")}>
            Template Studio
          </ActionButton>
          <ActionButton primary onClick={() => setNewDocument(true)}>
            + New document
          </ActionButton>
        </div>
      </header>
      <div className={styles.pills} role="group" aria-label="Workspace views">
        {tabs.map((tab) => (
          <button
            type="button"
            key={tab.id}
            className={view === tab.id ? styles.active : ""}
            aria-pressed={view === tab.id}
            onClick={() => setView(tab.id)}
          >
            {tab.label}
          </button>
        ))}
      </div>
      {view !== "shares" && <WorkflowCards onStart={setView} />}
      {view === "documents" && (
        <DocumentsLibrary clientId={clientId} onOpen={setSelected} />
      )}
      {view === "workflows" && (
        <div className={styles.info}>
          <h3>Templates and workflows</h3>
          <p>
            Start from a published campaign template or build a document using
            client meetings and supporting evidence.
          </p>
          <ActionButton onClick={() => setView("templates")}>
            Open Template Studio
          </ActionButton>
        </div>
      )}
      {view === "shares" && <WorkspaceShares />}
      <Modal
        open={newDocument}
        onOpenChange={setNewDocument}
        title="New document"
        description="Choose a workflow to get started."
        footer={
          <ActionButton onClick={() => setNewDocument(false)}>
            Cancel
          </ActionButton>
        }
      >
        <div className={styles.form}>
          <ActionButton
            onClick={() => {
              setNewDocument(false);
              setView("hillday");
            }}
          >
            Hill Day Schedule
          </ActionButton>
          <ActionButton
            onClick={() => {
              setNewDocument(false);
              setView("newsletter");
            }}
          >
            Newsletter
          </ActionButton>
          <ActionButton
            onClick={() => {
              setNewDocument(false);
              setView("templates");
            }}
          >
            Start from a template
          </ActionButton>
        </div>
      </Modal>
    </section>
  );
}

"use client";

import type {
  NewsletterBlock,
  NewsletterBody,
  WorkspaceDraftDocument,
} from "../../../../shared/capiro/operations/workspace-documents";
import {
  ActionButton,
  Badge,
  Field,
  Modal,
  Panel,
  SelectInput,
  TextInput,
  UnavailableAction,
} from "../../../../shared/module-ui";
import styles from "../workspace.module.css";
import { NewsletterComments } from "./NewsletterComments";
import { NewsletterPaper } from "./NewsletterPaper";
import { SelectTemplate } from "./NewsletterTemplates";
import { useNewsletter } from "./use-newsletter";
import { NewsletterStaging } from "./NewsletterStaging";

function BuilderTools({
  body,
  onChange,
}: {
  body: NewsletterBody;
  onChange: (body: NewsletterBody) => void;
}) {
  const kinds: NewsletterBlock["kind"][] = [
    "heading",
    "paragraph",
    "image",
    "button",
    "divider",
    "spacer",
    "social",
    "logo",
    "code",
  ];
  return (
    <aside className={styles.newsletterTools}>
      <strong>Add content</strong>
      {kinds.map((kind) => (
        <button
          key={kind}
          disabled={body.blocks.length >= 100}
          onClick={() =>
            onChange({
              ...body,
              blocks: [
                ...body.blocks,
                {
                  id: crypto.randomUUID(),
                  kind,
                  text: ["divider", "spacer"].includes(kind)
                    ? ""
                    : `New ${kind}`,
                  href: undefined,
                },
              ],
            })
          }
        >
          {kind[0]!.toUpperCase() + kind.slice(1)}
        </button>
      ))}
      <p className={styles.footnote}>
        Images and links are reviewed before use.
      </p>
    </aside>
  );
}

export function NewsletterWorkflow({
  onClose,
  existing,
  initialClientId = "",
}: {
  onClose: () => void;
  existing?: WorkspaceDraftDocument;
  initialClientId?: string;
}) {
  const {
    step,
    setStep,
    clients,
    clientId,
    setClientId,
    title,
    setTitle,
    body,
    draft,
    saved,
    setSaved,
    mobile,
    setMobile,
    history,
    future,
    confirmClose,
    setConfirmClose,
    pending,
    error,
    edit,
    select,
    undo,
    redo,
    save,
    documentId,
  } = useNewsletter({ onClose, existing, initialClientId });
  return (
    <fieldset
      disabled={pending}
      style={{ border: 0, padding: 0, margin: 0, minWidth: 0 }}
      className={styles.screen}
      data-design-node={
        step === "template"
          ? "976:190063"
          : step === "builder"
            ? "976:190222"
            : step === "review"
              ? "976:190381"
              : "976:190540"
      }
    >
      <nav className={styles.breadcrumb}>
        <button
          className={styles.link}
          onClick={() =>
            saved || step === "template" ? onClose() : setConfirmClose(true)
          }
        >
          Workspace
        </button>
        <span>/ {step === "template" ? "Create a newsletter" : title}</span>
      </nav>
      <header className={styles.heading}>
        <div>
          <h1>
            {step === "template"
              ? "Create a newsletter"
              : step === "review"
                ? "Newsletter preview & review"
                : step === "stage"
                  ? "Stage newsletter in Outreach"
                  : title}
          </h1>
          <p>
            {step === "template"
              ? "Select a starting point. Customize every section in the builder."
              : step === "stage"
                ? "Select a saved revision and an existing Outreach session."
                : "Newsletter builder"}
          </p>
        </div>
        {step !== "template" && (
          <div className={styles.actions}>
            {step === "builder" ? (
              <>
                <ActionButton disabled={pending} onClick={() => save(true)}>
                  Save and exit
                </ActionButton>
                <ActionButton onClick={() => setStep("review")}>
                  Preview & review
                </ActionButton>
              </>
            ) : (
              <ActionButton onClick={() => setStep("builder")}>
                Edit newsletter
              </ActionButton>
            )}
            <ActionButton primary onClick={() => setStep("stage")}>
              Stage in Outreach
            </ActionButton>
          </div>
        )}
      </header>
      {error && (
        <p role="alert" className={styles.error}>
          {error.message}
        </p>
      )}
      {step === "template" ? (
        <SelectTemplate onSelect={select} />
      ) : (
        <>
          <div className={styles.actions}>
            <Badge tone={saved ? "success" : "warning"}>
              {pending
                ? "Saving…"
                : saved
                  ? "All changes saved"
                  : "Unsaved changes"}
            </Badge>
            {step !== "stage" && (
              <>
                <ActionButton disabled={pending} onClick={() => save()}>
                  Save draft
                </ActionButton>
                <ActionButton
                  onClick={() => setMobile(false)}
                  aria-pressed={!mobile}
                >
                  Desktop
                </ActionButton>
                <ActionButton
                  onClick={() => setMobile(true)}
                  aria-pressed={mobile}
                >
                  Mobile
                </ActionButton>
              </>
            )}
          </div>
          {step === "builder" && (
            <>
              <div className={styles.grid}>
                <Field label="Subject" htmlFor="newsletter-subject">
                  <TextInput
                    id="newsletter-subject"
                    value={body.subject}
                    maxLength={400}
                    onChange={(event) =>
                      edit({ ...body, subject: event.target.value })
                    }
                  />
                </Field>
                <Field label="Preview text" htmlFor="newsletter-preview-text">
                  <TextInput
                    id="newsletter-preview-text"
                    value={body.preview}
                    maxLength={500}
                    onChange={(event) =>
                      edit({ ...body, preview: event.target.value })
                    }
                  />
                </Field>
              </div>
              <div className={styles.actions}>
                <ActionButton disabled={!history.length} onClick={undo}>
                  Undo
                </ActionButton>
                <ActionButton disabled={!future.length} onClick={redo}>
                  Redo
                </ActionButton>
              </div>
              <div className={styles.newsletterGrid}>
                <BuilderTools body={body} onChange={edit} />
                <NewsletterPaper
                  body={body}
                  mobile={mobile}
                  editable
                  onChange={edit}
                />
                <aside className={styles.info}>
                  <h3>Newsletter settings</h3>
                  <div className={styles.form}>
                    <Field label="Document name" htmlFor="newsletter-title">
                      <TextInput
                        id="newsletter-title"
                        value={title}
                        maxLength={500}
                        onChange={(event) => {
                          setTitle(event.target.value);
                          setSaved(false);
                        }}
                      />
                    </Field>
                    <Field label="Client" htmlFor="newsletter-client">
                      <SelectInput
                        id="newsletter-client"
                        disabled={Boolean(draft)}
                        value={clientId}
                        onValueChange={setClientId}
                        options={[
                          { value: "", label: "Firm newsletter" },
                          ...(clients.data?.items ?? []).map((client) => ({
                            value: client.id,
                            label: client.name,
                          })),
                        ]}
                      />
                    </Field>
                    <Field label="Firm name" htmlFor="newsletter-firm">
                      <TextInput
                        id="newsletter-firm"
                        value={body.firmName}
                        maxLength={200}
                        onChange={(event) =>
                          edit({ ...body, firmName: event.target.value })
                        }
                      />
                    </Field>
                    <Field label="Mailing address" htmlFor="newsletter-address">
                      <TextInput
                        id="newsletter-address"
                        value={body.mailingAddress}
                        maxLength={500}
                        onChange={(event) =>
                          edit({ ...body, mailingAddress: event.target.value })
                        }
                      />
                    </Field>
                    <ActionButton onClick={() => setStep("template")}>
                      Change template
                    </ActionButton>
                    <UnavailableAction reason="Newsletter template publication does not have a verified backend contract.">
                      Save as a template
                    </UnavailableAction>
                  </div>
                </aside>
              </div>
            </>
          )}
          {step === "review" && (
            <div className={styles.sponsorLayout}>
              <Panel>
                <p>SUBJECT {body.subject || "Not set"}</p>
                <p className={styles.footnote}>
                  PREVIEW {body.preview || "Not set"}
                </p>
                <NewsletterPaper body={body} mobile={mobile} />
              </Panel>
              <NewsletterComments documentId={documentId} />
            </div>
          )}
          {step === "stage" && (
            <Panel>
              <Badge tone={saved ? "success" : "warning"}>
                {saved ? "Revision saved" : "Save required"}
              </Badge>
              <h2 style={{ marginTop: 20 }}>{title}</h2>
              <div className={styles.stageCards}>
                <Panel title="Client">
                  {draft?.client ??
                    clients.data?.items.find((value) => value.id === clientId)
                      ?.name ??
                    "Firm"}
                </Panel>
                <Panel title="Status">
                  {saved ? "Draft saved" : "Unsaved changes"}
                </Panel>
                <Panel title="Delivery">Outreach</Panel>
              </div>
              {draft ? (
                <NewsletterStaging draftId={draft.id} saved={saved} />
              ) : (
                <p>
                  Save the newsletter before selecting a saved revision for
                  Outreach.
                </p>
              )}
              <div className={styles.actions} style={{ marginTop: 20 }}>
                <ActionButton onClick={() => setStep("builder")}>
                  Back to editor
                </ActionButton>
                {!saved && (
                  <ActionButton
                    primary
                    disabled={pending}
                    onClick={() => save()}
                  >
                    Save newsletter
                  </ActionButton>
                )}
              </div>
            </Panel>
          )}
        </>
      )}
      <Modal
        open={confirmClose}
        onOpenChange={setConfirmClose}
        title="Leave this newsletter?"
        description="Your unsaved edits will be lost."
        footer={
          <>
            <ActionButton onClick={() => setConfirmClose(false)}>
              Keep editing
            </ActionButton>
            <ActionButton primary onClick={onClose}>
              Discard unsaved edits
            </ActionButton>
          </>
        }
      >
        <p>Save the newsletter before closing to keep this revision.</p>
      </Modal>
    </fieldset>
  );
}

"use client";
import Link from "next/link";
import { useState } from "react";
import { useCapiroQuery } from "../../../../shared/capiro/queries";
import {
  ActionButton,
  Field,
  Panel,
  SelectInput,
} from "../../../../shared/module-ui";
import { requireCompatibleSponsor, type StagingActor } from "./staging-model";
import { useNewsletterStaging } from "./useNewsletterStaging";
import styles from "../workspace.module.css";

export function NewsletterStaging({
  draftId,
  saved,
}: {
  draftId: string;
  saved: boolean;
}) {
  const me = useCapiroQuery("me.read", {});
  if (!me.data)
    return (
      <p role={me.error ? "alert" : "status"}>
        {me.error?.message ?? "Checking current Core identity…"}
      </p>
    );
  const actor = {
    tenantId: me.data.tenant.id,
    userId: me.data.user.id,
    clerkUserId: me.data.user.clerkUserId,
  };
  return (
    <StagingSelection
      key={JSON.stringify([actor, draftId])}
      actor={actor}
      draftId={draftId}
      saved={saved}
    />
  );
}

function StagingSelection({
  actor,
  draftId,
  saved,
}: {
  actor: StagingActor;
  draftId: string;
  saved: boolean;
}) {
  const flow = useNewsletterStaging(actor, draftId);
  const [selectedVersion, setVersion] = useState("");
  const [selectedSession, setSession] = useState("");
  const [offset, setOffset] = useState(0);
  const [reviewed, setReviewed] = useState("");
  const original = flow.retained.record;
  const versionId = original?.body.versionId ?? selectedVersion;
  const sessionId = original?.sessionId ?? selectedSession;
  const versions = useCapiroQuery(
    "workspace.draft.versions",
    { params: { draftId } },
    { enabled: flow.retained.ready },
  );
  const sessions = useCapiroQuery(
    "engagement.sessions",
    { query: { limit: 100, offset } },
    { enabled: flow.retained.ready },
  );
  const revision = useCapiroQuery(
    "workspace.newsletter.revision",
    { params: { draftId, versionId } },
    { enabled: flow.retained.ready && !!versionId },
  );
  const destination = useCapiroQuery(
    "engagement.session",
    { params: { sessionId } },
    { enabled: flow.retained.ready && !!sessionId },
  );
  const selected = revision.data;
  const target = destination.data;
  let unavailable = "";
  try {
    if (
      selected &&
      (selected.draftId !== draftId ||
        selected.versionId !== versionId ||
        (original && selected.snapshotHash !== original.body.snapshotHash))
    )
      throw new Error(
        "The saved revision receipt does not match the selection.",
      );
    if (target && target.session.id !== sessionId)
      throw new Error(
        "The Outreach receipt does not match the selected session.",
      );
    if (selected && target)
      requireCompatibleSponsor(selected, target.spec.sponsor);
    if (
      !original &&
      target &&
      (target.session.archivedAt || target.session.status !== "active")
    )
      throw new Error("This Outreach session is unavailable for new staging.");
  } catch (cause) {
    unavailable =
      cause instanceof Error ? cause.message : "Selection unavailable.";
  }
  const reviewKey = JSON.stringify([
    versionId,
    selected?.snapshotHash,
    sessionId,
    target?.currentStateVersion,
  ]);
  const ready =
    selected &&
    target &&
    !unavailable &&
    !revision.loading &&
    !destination.loading;
  const error = flow.retained.error ?? unavailable ?? "";
  if (!flow.retained.ready)
    return (
      <div role={flow.retained.error ? "alert" : "status"}>
        <p>{error || "Checking saved staging recovery…"}</p>
        {flow.retained.error && (
          <ActionButton onClick={flow.retained.retry}>
            Retry staging recovery
          </ActionButton>
        )}
      </div>
    );
  return (
    <div className={styles.form}>
      <p>
        {saved
          ? "Choose a saved revision to stage."
          : "Unsaved editor changes are excluded. Choose an existing saved revision, or save in the editor first."}{" "}
        Staging replaces the session’s content skeleton. It does not generate or
        send messages.
      </p>
      {original ? (
        <p role="status">
          Original staging request retained: {original.body.requestId}. Recovery
          uses its original revision and state version{" "}
          {original.body.expectedStateVersion}.
        </p>
      ) : (
        <>
          <Field label="Saved Newsletter revision" htmlFor="staging-version">
            <SelectInput
              id="staging-version"
              value={selectedVersion}
              disabled={flow.busy}
              onValueChange={setVersion}
              placeholder="Choose saved revision"
              options={(versions.data ?? [])
                .filter((item) => item.draftId === draftId)
                .map((item) => ({
                  value: item.id,
                  label: `${item.label ?? "Saved revision"} · ${item.createdAt} · ${item.id}`,
                }))}
            />
          </Field>
          <Field label="Existing Outreach session" htmlFor="staging-session">
            <SelectInput
              id="staging-session"
              value={selectedSession}
              disabled={flow.busy}
              onValueChange={setSession}
              placeholder="Choose existing session"
              options={(sessions.data ?? []).map((item) => ({
                value: item.id,
                label: `${item.title ?? item.id} · ${item.status}`,
              }))}
            />
          </Field>
          <div className={styles.actions}>
            <ActionButton
              disabled={offset === 0 || flow.busy}
              onClick={() => {
                setOffset(offset - 100);
                setSession("");
              }}
            >
              Previous sessions
            </ActionButton>
            <ActionButton
              disabled={sessions.data?.length !== 100 || flow.busy}
              onClick={() => {
                setOffset(offset + 100);
                setSession("");
              }}
            >
              More sessions
            </ActionButton>
          </div>
        </>
      )}
      {[versions.error, sessions.error, revision.error, destination.error]
        .filter(Boolean)
        .map((failure, index) => (
          <p role="alert" key={index}>
            {failure!.message} Saved revision staging is unavailable until the
            source and destination can be verified.
          </p>
        ))}
      {(revision.loading || destination.loading) && (
        <p role="status">Checking selected revision and Outreach session…</p>
      )}
      {unavailable && <p role="alert">{unavailable}</p>}
      {ready && (
        <Panel title="Review saved content for Outreach">
          <p>
            Revision {selected.versionId} · saved {selected.savedAt} · author{" "}
            {selected.authorId} ({selected.authorKind})
          </p>
          <p style={{ overflowWrap: "anywhere" }}>
            Snapshot SHA-256: {selected.snapshotHash}
          </p>
          <p>
            Scope:{" "}
            {selected.clientId
              ? `Client ${selected.clientId}`
              : "Explicit firm content"}
          </p>
          <h3>{selected.contentSkeleton.subject || "No subject"}</h3>
          <p style={{ whiteSpace: "pre-wrap", overflowWrap: "anywhere" }}>
            {selected.contentSkeleton.body}
          </p>
          <p>
            Destination: {target.session.title ?? sessionId} · current version{" "}
            {target.currentStateVersion}. Rich formatting, images and
            attachments are not included.
          </p>
          {!flow.receipt && (
            <label>
              <input
                type="checkbox"
                checked={reviewed === reviewKey}
                disabled={flow.busy}
                onChange={(event) =>
                  setReviewed(event.target.checked ? reviewKey : "")
                }
              />{" "}
              I reviewed this saved text and selected destination.
            </label>
          )}
        </Panel>
      )}
      {flow.error && <p role="alert">{flow.error}</p>}
      {flow.receipt ? (
        <Panel title="Saved revision staged">
          <p role="status">
            Receipt {flow.receipt.receiptId} · applied state version{" "}
            {flow.receipt.stateVersion}
            {flow.receipt.replayed ? " · recovered original receipt" : ""}. No
            message was sent.
          </p>
          <Link
            href={`/modules/engagement?view=outreach&session=${encodeURIComponent(sessionId)}`}
          >
            Open selected Outreach session
          </Link>
          <ActionButton
            disabled={flow.busy}
            onClick={() => void flow.acknowledge()}
          >
            Acknowledge staging receipt
          </ActionButton>
        </Panel>
      ) : (
        <ActionButton
          primary
          disabled={!ready || reviewed !== reviewKey || flow.busy}
          onClick={() =>
            ready &&
            void flow.stage({
              sessionId,
              draftId,
              versionId,
              snapshotHash: selected.snapshotHash,
              expectedStateVersion: target.currentStateVersion,
            })
          }
        >
          {flow.busy
            ? "Checking staging…"
            : original
              ? "Recover original staging"
              : "Stage saved revision"}
        </ActionButton>
      )}
      <ActionButton
        disabled={flow.busy}
        onClick={() => {
          setReviewed("");
          versions.reload();
          sessions.reload();
          revision.reload();
          destination.reload();
        }}
      >
        Refresh saved revision and session
      </ActionButton>
    </div>
  );
}

"use client";
import { useRef, useState } from "react";
import { useCapiro } from "../../../../shared/capiro/CapiroBoundary";
import { CapiroApiError } from "../../../../shared/capiro/http";
import type { NewsletterStagingReceipt } from "../../../../shared/capiro/operations/workspace-newsletter-staging";
import { useRetainedIntent } from "../../../../shared/session/recovery/useRetainedIntent";
import {
  acknowledgeRecovery,
  reserveRecovery,
  RecoveryStorageError,
} from "../../../../shared/session/recovery/journal";
import {
  readStagingSelection,
  stagingRecovery,
  stagingScope,
  verifyStagingActor,
  verifyStagingReceipt,
  type StagingActor,
  type StagingIntent,
} from "./staging-model";

export function useNewsletterStaging(actor: StagingActor, draftId: string) {
  const api = useCapiro();
  const scope = stagingScope(actor, draftId);
  const retained = useRetainedIntent(scope, stagingRecovery, (signal, guard) =>
    verifyStagingActor(api, actor, draftId, signal, guard),
  );
  const [receipt, setReceipt] = useState<NewsletterStagingReceipt>();
  const [error, setError] = useState("");
  const [busy, setBusy] = useState(false);
  const working = useRef(false);
  async function stage(
    selection: Omit<StagingIntent["body"], "requestId"> & { sessionId: string },
  ) {
    if (working.current || !retained.ready || receipt) return;
    working.current = true;
    setBusy(true);
    setError("");
    let authorized = false;
    try {
      await retained.verify();
      const original = retained.record ?? {
        sessionId: selection.sessionId,
        body: {
          requestId: crypto.randomUUID(),
          draftId,
          versionId: selection.versionId,
          snapshotHash: selection.snapshotHash,
          expectedStateVersion: selection.expectedStateVersion,
        },
      };
      const current = await readStagingSelection(
        api,
        draftId,
        original.body.versionId,
        original.sessionId,
        retained.signal(),
        retained.guard,
      );
      if (current.revision.snapshotHash !== original.body.snapshotHash)
        throw new Error(
          "The saved revision hash changed. The original request remains held.",
        );
      if (
        !retained.record &&
        (current.session.currentStateVersion !==
          original.body.expectedStateVersion ||
          current.session.session.archivedAt ||
          current.session.session.status !== "active")
      )
        throw new Error(
          "The Outreach session changed or is unavailable. Refresh and review its current version before staging.",
        );
      authorized = true;
      const reserved = await reserveRecovery(
        scope,
        original.body.requestId,
        original,
        stagingRecovery,
        retained.guard,
      );
      retained.install(reserved);
      if (JSON.stringify(reserved) !== JSON.stringify(original))
        throw new Error(
          "Another view retained an original staging request. Review and recover that original request.",
        );
      const result = await api.request(
        "workspace.newsletter.stage",
        { params: { sessionId: original.sessionId }, body: original.body },
        { signal: retained.signal() },
      );
      retained.guard();
      verifyStagingReceipt(result, original, current.revision);
      setReceipt(result);
    } catch (cause) {
      if (cause instanceof DOMException && cause.name === "AbortError") return;
      if (
        !authorized ||
        cause instanceof RecoveryStorageError ||
        (cause instanceof CapiroApiError && [401, 403].includes(cause.status))
      )
        retained.block(cause);
      setError(
        cause instanceof Error
          ? cause.message
          : "Staging is unconfirmed. Recover only the original request.",
      );
    } finally {
      working.current = false;
      setBusy(false);
    }
  }
  async function acknowledge() {
    if (working.current || !receipt || !retained.record) return;
    working.current = true;
    setBusy(true);
    try {
      await retained.verify();
      const current = await readStagingSelection(
        api,
        draftId,
        retained.record.body.versionId,
        retained.record.sessionId,
        retained.signal(),
        retained.guard,
      );
      if (current.revision.snapshotHash !== retained.record.body.snapshotHash)
        throw new Error(
          "The original saved revision is unavailable. Its staging receipt remains retained.",
        );
      verifyStagingReceipt(receipt, retained.record, current.revision);
      await acknowledgeRecovery(scope, receipt.batchId, retained.guard);
      retained.install(null);
      setReceipt(undefined);
    } catch (cause) {
      retained.block(cause);
    } finally {
      working.current = false;
      setBusy(false);
    }
  }
  return { retained, receipt, error, busy, stage, acknowledge };
}

